    """Restore 6-masked cells using diagonal symmetry and repeated rows."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # First use the demonstrated exact main-diagonal symmetry.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 6 and grid[c][r] != 6:
                out[r][c] = grid[c][r]

    # Some symmetric pairs are both masked. Recover these from rows whose
    # remaining visible cells match exactly (repeated rows in the source).
    for _ in range(h):
        changed = False
        for r in range(h):
            missing = [c for c in range(w) if out[r][c] == 6]
            if not missing:
                continue
            candidates = []
            for rr in range(h):
                if rr == r:
                    continue
                overlap = [c for c in range(w)
